     1→/**
     2→ * CLAUDELang v6.0 - Notion 통합 모듈
     3→ *
     4→ * Notion MCP를 활용하여 자동 포스팅 결과를 Notion에 발행
     5→ * FreeLang Marketing Team Notion 활용
     6→ */
     7→
     8→const { AutoPoster } = require('./auto-post.js');
     9→
    10→/**
    11→ * NotionIntegration 클래스
    12→ * Notion MCP와의 통신을 담당
    13→ */
    14→class NotionIntegration {
    15→  constructor(options = {}) {
    16→    this.autoPoster = new AutoPoster(options.notionApiToken);
    17→    this.notionDatabaseId = options.databaseId || null;
    18→    this.pageTitle = options.pageTitle || 'CLAUDELang 실행 결과';
    19→    this.tags = options.tags || ['CLAUDELang', 'AutoPost', 'v6.0'];
    20→  }
    21→
    22→  /**
    23→   * CLAUDELang 코드 실행 및 Notion에 발행
    24→   */
    25→  async executeAndPost(claudelangCode, metadata = {}) {
    26→    try {
    27→      // 1. 코드 실행 및 보고서 생성
    28→      const report = await this.autoPoster.run(claudelangCode, metadata);
    29→
    30→      // 2. Notion 페이지 생성
    31→      const notionPageData = this.buildNotionPage(report);
    32→
    33→      console.log('[NotionIntegration] Notion 페이지 데이터:');
    34→      console.log(JSON.stringify(notionPageData, null, 2));
    35→
    36→      return {
    37→        success: true,
    38→        report: report,
    39→        notionPageData: notionPageData,
    40→      };
    41→    } catch (error) {
    42→      console.error('[NotionIntegration] 에러:', error.message);
    43→      return {
    44→        success: false,
    45→        error: error.message,
    46→      };
    47→    }
    48→  }
    49→
    50→  /**
    51→   * Notion 페이지 데이터 구성
    52→   * Notion MCP 형식으로 변환
    53→   */
    54→  buildNotionPage(report) {
    55→    const { compilation, execution, metadata } = report;
    56→
    57→    return {
    58→      title: `CLAUDELang 실행: ${metadata.filename || '자동 실행'}`,
    59→      content: this.buildPageContent(report),
    60→      properties: {
    61→        '파일명': metadata.filename || 'Unknown',
    62→        '실행시간': new Date().toLocaleString('ko-KR'),
    63→        '컴파일 상태': compilation.success ? '성공' : '실패',
    64→        '실행 상태': execution.success ? '성공' : '실패',
    65→        '태그': this.tags,
    66→      },
    67→      cover: {
    68→        emoji: execution.success ? '✅' : '❌',
    69→      },
    70→    };
    71→  }
    72→
    73→  /**
    74→   * Notion 페이지 콘텐츠 생성
    75→   */
    76→  buildPageContent(report) {
    77→    const { compilation, execution, metadata } = report;
    78→
    79→    const sections = [];
    80→
    81→    // 요약 섹션
    82→    sections.push({
    83→      type: 'heading_2',
    84→      content: '요약',
    85→    });
    86→
    87→    sections.push({
    88→      type: 'paragraph',
    89→      content: [
    90→        {
    91→          text: `파일: ${metadata.filename || 'Unknown'}`,
    92→          bold: false,
    93→        },
    94→      ],
    95→    });
    96→
    97→    sections.push({
    98→      type: 'table',
    99→      rows: [
   100→        ['항목', '상태'],
   101→        ['컴파일', compilation.success ? '✅ 성공' : '❌ 실패'],
   102→        ['실행', execution.success ? '✅ 성공' : '❌ 실패'],
   103→        ['실행 시간', `${execution.executionTime}ms`],
   104→        ['메모리 사용', `${execution.memoryUsage.toFixed(2)}MB`],
   105→      ],
   106→    });
   107→
   108→    // 결과 섹션
   109→    if (execution.output.length > 0) {
   110→      sections.push({
   111→        type: 'heading_2',
   112→        content: '실행 결과',
   113→      });
   114→
   115→      sections.push({
   116→        type: 'code',
   117→        language: 'text',
   118→        content: execution.output.join('\n'),
   119→      });
   120→    }
   121→
   122→    // 에러 섹션
   123→    if (compilation.errors.length > 0) {
   124→      sections.push({
   125→        type: 'heading_2',
   126→        content: '컴파일 에러',
   127→      });
   128→
   129→      compilation.errors.forEach(error => {
   130→        sections.push({
   131→          type: 'paragraph',
   132→          content: [
   133→            {
   134→              text: `❌ ${error}`,
   135→              color: 'red',
   136→            },
   137→          ],
   138→        });
   139→      });
   140→    }
   141→
   142→    if (execution.error) {
   143→      sections.push({
   144→        type: 'paragraph',
   145→        content: [
   146→          {
   147→            text: `❌ 실행 에러: ${execution.error}`,
   148→            color: 'red',
   149→          },
   150→        ],
   151→      });
   152→    }
   153→
   154→    // VT 코드 섹션
   155→    if (compilation.code) {
   156→      sections.push({
   157→        type: 'heading_2',
   158→        content: 'VT 바이트코드',
   159→      });
   160→
   161→      const vtCodePreview = compilation.code
   162→        .split('\n')
   163→        .slice(0, 15)
   164→        .join('\n');
   165→
   166→      sections.push({
   167→        type: 'code',
   168→        language: 'lisp',
   169→        content: vtCodePreview,
   170→      });
   171→    }
   172→
   173→    return sections;
   174→  }
   175→
   176→  /**
   177→   * 배치 처리 및 Notion 발행
   178→   */
   179→  async batchExecuteAndPost(filePaths, databaseId = null) {
   180→    const results = [];
   181→
   182→    console.log(`[NotionIntegration] ${filePaths.length}개 파일 처리 시작...\n`);
   183→
   184→    for (const filePath of filePaths) {
   185→      try {
   186→        const fs = require('fs');
   187→        const code = fs.readFileSync(filePath, 'utf-8');
   188→        const metadata = {
   189→          filename: require('path').basename(filePath),
   190→          filePath: filePath,
   191→        };
   192→
   193→        const result = await this.executeAndPost(code, metadata);
   194→        results.push(result);
   195→      } catch (error) {
   196→        console.error(`[NotionIntegration] 파일 처리 실패: ${filePath}`, error.message);
   197→      }
   198→    }
   199→
   200→    // 요약 보고서 생성
   201→    const summary = this.generateSummary(results);
   202→
   203→    return {
   204→      results: results,
   205→      summary: summary,
   206→    };
   207→  }
   208→
   209→  /**
   210→   * 요약 보고서 생성
   211→   */
   212→  generateSummary(results) {
   213→    const successCount = results.filter(r => r.success && r.report.execution.success).length;
   214→    const failureCount = results.length - successCount;
   215→
   216→    return {
   217→      totalFiles: results.length,
   218→      successful: successCount,
   219→      failed: failureCount,
   220→      timestamp: new Date().toISOString(),
   221→      details: results.map(r => ({
   222→        filename: r.report?.metadata?.filename || 'Unknown',
   223→        status: r.success ? (r.report.execution.success ? '성공' : '실패') : '에러',
   224→        message: r.error || '정상 처리됨',
   225→      })),
   226→    };
   227→  }
   228→
   229→  /**
   230→   * Notion에 요약 페이지 생성
   231→   */
   232→  buildSummaryPage(summary) {
   233→    const sections = [];
   234→
   235→    sections.push({
   236→      type: 'heading_1',
   237→      content: 'CLAUDELang 자동 포스팅 요약',
   238→    });
   239→
   240→    sections.push({
   241→      type: 'paragraph',
   242→      content: [
   243→        {
   244→          text: `처리 시간: ${summary.timestamp}`,
   245→        },
   246→      ],
   247→    });
   248→
   249→    sections.push({
   250→      type: 'table',
   251→      rows: [
   252→        ['항목', '값'],
   253→        ['총 파일 수', summary.totalFiles.toString()],
   254→        ['성공', summary.successful.toString()],
   255→        ['실패', summary.failed.toString()],
   256→        ['성공률', `${((summary.successful / summary.totalFiles) * 100).toFixed(1)}%`],
   257→      ],
   258→    });
   259→
   260→    sections.push({
   261→      type: 'heading_2',
   262→      content: '상세 결과',
   263→    });
   264→
   265→    sections.push({
   266→      type: 'table',
   267→      rows: [
   268→        ['파일명', '상태', '메모'],
   269→        ...summary.details.map(d => [
   270→          d.filename,
   271→          d.status,
   272→          d.message,
   273→        ]),
   274→      ],
   275→    });
   276→
   277→    return {
   278→      title: `CLAUDELang 자동 포스팅 - ${new Date().toLocaleDateString('ko-KR')}`,
   279→      content: sections,
   280→    };
   281→  }
   282→}
   283→
   284→/**
   285→ * 간편한 사용을 위한 헬퍼 함수
   286→ */
   287→async function autoPostToNotion(claudelangCode, options = {}) {
   288→  const integration = new NotionIntegration(options);
   289→  return await integration.executeAndPost(claudelangCode, options.metadata);
   290→}
   291→
   292→// 내보내기
   293→if (typeof module !== 'undefined' && module.exports) {
   294→  module.exports = {
   295→    NotionIntegration,
   296→    autoPostToNotion,
   297→  };
   298→}
